#define MAX_ITERATIONS 12
#define PI 3.14159265359


vec3 palette(float t) {
    // New dramatic, dark color palette
    vec3 a = vec3(0.1, 0.1, 0.1);  // Darker base
    vec3 b = vec3(0.3, 0.3, 0.3);  // Subtle variation
    vec3 c = vec3(0.8, 0.8, 0.8);  // Controls color spread
    vec3 d = vec3(0.0, 0.1, 0.2);  // Shift towards cool tones

    return a + b * cos(2.0 * PI * (c * t + d));
}

float sdSmoothCircle(vec2 p, float r) {
    return length(p) - r;
}

float sdFlower(vec2 p, float r, int n) {
    float a = atan(p.y, p.x);
    float b = 2.0 * PI / float(n);
    return smoothstep(0.0, 0.05, abs(length(p) - r * (0.9 + 0.1 * cos(floor(0.5 + a/b) * b - a))));
}

mat2 rot2d(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * (1.0 / 4.0);
}

float flowField(vec2 uv, float time) {
    vec2 gv = fract(uv) - 0.5;
    vec2 id = floor(uv);
    float n = fract(sin(dot(id, vec2(12.9898, 78.233))) * 43758.5453);
    float angle = n * 2.0 * PI + time;
    return dot(gv, vec2(cos(angle), sin(angle)));
}

float fractalLayer(vec2 uv, float time, float scale) {
    float d = 1e10;
    float flow = 0.0;

    for (int i = 0; i < MAX_ITERATIONS; i++) {
        flow += flowField(uv * (0.5 + float(i) * 0.1), time * (1.0 + float(i) * 0.05)) * (1.0 / float(i+1));
        uv = abs(uv) - 0.5 * scale;
        uv *= rot2d(time * 0.1 + flow * 0.5);

        float circle = sdSmoothCircle(uv, 0.3 * scale);
        float flower = sdFlower(uv, 0.25 * scale, 5 + i % 3);

        d = smin(d, mix(circle, flower, sin(time * 0.2 + float(i) * 0.1) * 0.5 + 0.5) / scale, 0.1);

        scale *= 0.8;
    }
    return d;
}

// Shrinkwrap effect function
float shrinkwrap(vec2 uv, float time, float scale) {
    float d = fractalLayer(uv, time, scale);
    return smoothstep(0.0, 0.1, abs(d));
}


vec3 screenBlend(vec3 a, vec3 b) {
    return 1.0 - (1.0 - a) * (1.0 - b);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
    float time = iTime * 0.3;

    // Subtle zoom and rotation
    float zoom = 1.0 + 0.1 * sin(time * 0.2);
    uv *= zoom;
    uv *= rot2d(time * 0.05);

    // Gentle mouse interaction
    if (iMouse.z > 0.0) {
        vec2 mouseUV = (iMouse.xy - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
        uv += mouseUV * 0.05;
    }

    float d = fractalLayer(uv, time, 1.0);

    // Sophisticated color palette
    vec3 col = palette(d * 0.4 + time * 0.1);
    col *= 1.0 - exp(-6.0 * abs(d));
    col *= 0.8 + 0.2 * cos(150.0 * d);
    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 0.01, abs(d)));

    // Subtle glow
    float glow = 0.0;
    for (int i = 1; i < 5; i++) {
        glow += exp(-2.0 * abs(d)) / float(i);
    }
    col += glow * palette(time * 0.1) * 0.25;

    // Apply shrinkwrap effect
    float shrink = shrinkwrap(uv, time, 1.0);
    vec3 shrinkCol = vec3(shrink) * 0.25;

    // Blend original and shrinkwrap using screen blend mode
    col = screenBlend(col, shrinkCol);

    // Gentle vignette
    float vignette = smoothstep(1.2, 0.5, length(uv));
    col *= mix(0.8, 1.0, vignette);

    // Subtle film grain
    float grain = fract(sin(dot(fragCoord, vec2(12.9898, 78.233))) * 43758.5453);
    col += (grain - 0.5) * 0.015;

    fragColor = vec4(col, 1.0);
}
